/// Crawl multiple seed URLs concurrently, each following links to configured depth.
#[allow(clippy::missing_errors_doc)]
#[wasm_bindgen(js_name = "batchCrawl")]
pub async fn batch_crawl(engine: WasmCrawlEngineHandle, urls: Vec<String>) -> Result<WasmBatchCrawlResults, JsValue> {
    let result = crawlberg::batch_crawl(&engine.inner, urls)
        .await
        .map_err(|e| JsValue::from_str(&e.to_string()))?;
    Ok(WasmBatchCrawlResults::from(result))
}

/// Scrape multiple URLs concurrently.
#[allow(clippy::missing_errors_doc)]
#[wasm_bindgen(js_name = "batchScrape")]
pub async fn batch_scrape(engine: WasmCrawlEngineHandle, urls: Vec<String>) -> Result<WasmBatchScrapeResults, JsValue> {
    let result = crawlberg::batch_scrape(&engine.inner, urls)
        .await
        .map_err(|e| JsValue::from_str(&e.to_string()))?;
    Ok(WasmBatchScrapeResults::from(result))
}

/// Crawl a website starting from `url`, following links up to the configured depth.
#[allow(clippy::missing_errors_doc)]
#[wasm_bindgen]
pub async fn crawl(engine: WasmCrawlEngineHandle, url: String) -> Result<WasmCrawlResult, JsValue> {
    let result = crawlberg::crawl(&engine.inner, &url)
        .await
        .map_err(|e| JsValue::from_str(&e.to_string()))?;
    Ok(WasmCrawlResult::from(result))
}

/// Create a new crawl engine with the given configuration.
///
/// If `config` is `None`, uses `CrawlConfig.default()`.
/// Returns an error if the configuration is invalid.
#[allow(clippy::missing_errors_doc)]
#[wasm_bindgen(js_name = "createEngine")]
pub fn create_engine(config: Option<WasmCrawlConfig>) -> Result<WasmCrawlEngineHandle, JsValue> {
    let config_core: Option<crawlberg::CrawlConfig> = config.map(Into::into);

    let result = crawlberg::create_engine(config_core).map_err(|e| JsValue::from_str(&e.to_string()))?;
    Ok(WasmCrawlEngineHandle {
        inner: Arc::new(result),
    })
}

/// Convert markdown links to numbered citations.
///
/// `[Example](https://example.com)` becomes `Example[1]`
/// with `[1]: https://example.com` in the reference list.
/// Images `![alt](url)` are preserved unchanged.
#[wasm_bindgen(js_name = "generateCitations")]
pub fn generate_citations(markdown: String) -> WasmCitationResult {
    crawlberg::generate_citations(&markdown).into()
}

/// Execute browser actions on a single page.
#[allow(clippy::missing_errors_doc)]
#[wasm_bindgen]
pub async fn interact(
    engine: WasmCrawlEngineHandle,
    url: String,
    actions: Vec<WasmPageAction>,
) -> Result<WasmInteractionResult, JsValue> {
    let actions_core: Vec<crawlberg::PageAction> = actions.into_iter().map(Into::into).collect();
    let result = crawlberg::interact(&engine.inner, &url, actions_core)
        .await
        .map_err(|e| JsValue::from_str(&e.to_string()))?;
    Ok(WasmInteractionResult::from(result))
}

/// Discover all pages on a website by following links and sitemaps.
#[allow(clippy::missing_errors_doc)]
#[wasm_bindgen(js_name = "mapUrls")]
pub async fn map_urls(engine: WasmCrawlEngineHandle, url: String) -> Result<WasmMapResult, JsValue> {
    let result = crawlberg::map_urls(&engine.inner, &url)
        .await
        .map_err(|e| JsValue::from_str(&e.to_string()))?;
    Ok(WasmMapResult::from(result))
}

/// Scrape a single URL, returning extracted page data.
#[allow(clippy::missing_errors_doc)]
#[wasm_bindgen]
pub async fn scrape(engine: WasmCrawlEngineHandle, url: String) -> Result<WasmScrapeResult, JsValue> {
    let result = crawlberg::scrape(&engine.inner, &url)
        .await
        .map_err(|e| JsValue::from_str(&e.to_string()))?;
    Ok(WasmScrapeResult::from(result))
}

