/// Return the error code string for a `crawlberg::CrawlError` variant.
#[allow(dead_code)]
fn crawl_error_error_code(e: &crawlberg::CrawlError) -> &'static str {
    #[allow(unreachable_patterns)]
    match e {
        crawlberg::CrawlError::NotFound { .. } => "not_found",
        crawlberg::CrawlError::Unauthorized { .. } => "unauthorized",
        crawlberg::CrawlError::Forbidden { .. } => "forbidden",
        crawlberg::CrawlError::WafBlocked { .. } => "waf_blocked",
        crawlberg::CrawlError::Timeout { .. } => "timeout",
        crawlberg::CrawlError::RateLimited { .. } => "rate_limited",
        crawlberg::CrawlError::ServerError { .. } => "server_error",
        crawlberg::CrawlError::BadGateway { .. } => "bad_gateway",
        crawlberg::CrawlError::Gone { .. } => "gone",
        crawlberg::CrawlError::Connection { .. } => "connection",
        crawlberg::CrawlError::Dns { .. } => "dns",
        crawlberg::CrawlError::Ssl { .. } => "ssl",
        crawlberg::CrawlError::DataLoss { .. } => "data_loss",
        crawlberg::CrawlError::BrowserError { .. } => "browser_error",
        crawlberg::CrawlError::BrowserTimeout { .. } => "browser_timeout",
        crawlberg::CrawlError::InvalidConfig { .. } => "invalid_config",
        crawlberg::CrawlError::Unsupported { .. } => "unsupported",
        crawlberg::CrawlError::SsrfPolicyViolation { .. } => "ssrf_policy_violation",
        crawlberg::CrawlError::Other { .. } => "other",
        _ => "crawl_error",
    }
}

/// Convert a `crawlberg::CrawlError` error to a `JsValue` object with `code` and `message` fields.
#[allow(dead_code)]
fn crawl_error_to_js_value(e: crawlberg::CrawlError) -> wasm_bindgen::JsValue {
    let code = crawl_error_error_code(&e);
    let message = e.to_string();
    let obj = js_sys::Object::new();
    js_sys::Reflect::set(&obj, &"code".into(), &code.into()).ok();
    js_sys::Reflect::set(&obj, &"message".into(), &message.into()).ok();
    obj.into()
}

/// Return the error code string for a `crawlberg::SsrfError` variant.
#[allow(dead_code)]
fn ssrf_error_error_code(e: &crawlberg::SsrfError) -> &'static str {
    #[allow(unreachable_patterns)]
    match e {
        crawlberg::SsrfError::DeniedByPolicy { .. } => "denied_by_policy",
        crawlberg::SsrfError::NotOnAllowlist => "not_on_allowlist",
        crawlberg::SsrfError::InvalidCidr(..) => "invalid_cidr",
        crawlberg::SsrfError::DnsResolutionFailed(..) => "dns_resolution_failed",
        crawlberg::SsrfError::InvalidUrl(..) => "invalid_url",
        crawlberg::SsrfError::DisallowedScheme(..) => "disallowed_scheme",
        crawlberg::SsrfError::TooManyRedirects => "too_many_redirects",
        _ => "ssrf_error",
    }
}

/// Convert a `crawlberg::SsrfError` error to a `JsValue` object with `code` and `message` fields.
#[allow(dead_code)]
fn ssrf_error_to_js_value(e: crawlberg::SsrfError) -> wasm_bindgen::JsValue {
    let code = ssrf_error_error_code(&e);
    let message = e.to_string();
    let obj = js_sys::Object::new();
    js_sys::Reflect::set(&obj, &"code".into(), &code.into()).ok();
    js_sys::Reflect::set(&obj, &"message".into(), &message.into()).ok();
    obj.into()
}
